/**
 * Shared contracts for LocalSEO AI.
 *
 * These types are frozen first (per the plan's first 20 minutes) so every
 * module can build against them in parallel.
 *
 * Data provenance rule: everything is labelled as measured (deterministic
 * tool output), client (from business.json / the user) or ai-suggestion
 * (generated by Gemma). The model never invents measured data.
 */

/** Finding severity, used to sort and prioritise the report. */
export type Severity = 'high' | 'medium' | 'low';

/** Where a piece of information comes from. */
export type SourceKind = 'measured' | 'client' | 'ai-suggestion';

/** One audit finding, tied to concrete evidence (file or URL). */
export interface Finding {
  id: string;
  rule: string; // e.g. 'missing-meta-description'
  severity: Severity;
  file?: string; // affected file
  url?: string; // or affected URL
  evidence: string; // measured proof
  fixable: boolean;
}

/** Result of one audit pass. */
export interface AuditResult {
  score: number; // indicative, 0–100
  findings: Finding[];
}

/** A proposed correction, shown as a diff before validation. */
export interface Fix {
  findingId: string;
  file: string;
  diff: string; // displayed before validation
  source: SourceKind;
}

/** Confirmed business information (business.json). Source of truth for JSON-LD. */
export interface BusinessInfo {
  name: string;
  city: string;
  phone: string;
  address: string;
  language?: 'fr' | 'en'; // primary site language
}

/** Known audit rule ids used by the AuditModule. */
export const AuditRules = {
  MissingTitle: 'missing-title',
  MissingMetaDescription: 'missing-meta-description',
  MissingH1: 'missing-h1',
  MissingCanonical: 'missing-canonical',
  MissingOpenGraph: 'missing-open-graph',
  MissingTwitterCard: 'missing-twitter-card',
  MissingAltText: 'missing-alt-text',
  MissingRobots: 'missing-robots',
  MissingSitemap: 'missing-sitemap',
  MissingHreflang: 'missing-hreflang',
  HeavyImage: 'heavy-image',
} as const;

export type AuditRule = (typeof AuditRules)[keyof typeof AuditRules];
